```sql
/* Выбираем молекулы, у которых есть одинарные связи (bond_type = '-') */
/* и которые не являются канцерогенными (label = '-') */
/* Возвращаем топ-3 уникальных molecule_id в алфавитном порядке */
SELECT DISTINCT m."molecule_id"
FROM "molecule" m
JOIN "bond" b ON b."molecule_id" = m."molecule_id"
WHERE m."label" = '-'
  AND b."bond_type" = '-'
ORDER BY m."molecule_id"
LIMIT 3;
```

```sql
/* Выбираем молекулы, не являющиеся канцерогенными (label = '-'), */
/* у которых количество атомов больше 5 */
SELECT m."molecule_id", m."label"
FROM "molecule" m
JOIN "atom" a ON a."molecule_id" = m."molecule_id"
WHERE m."label" = '-'
GROUP BY m."molecule_id", m."label"
HAVING COUNT(a."atom_id") > 5;
```

```sql
/* Вычисляем процент молекул, содержащих водород (element = 'h'), среди молекул с канцерогенными соединениями (label = '+') */
SELECT
    /* Доля молекул с водородом среди канцерогенных, умноженная на 100 */
    SUM(CASE WHEN LOWER(a."element") = 'h' THEN 1 ELSE 0 END) * 100.0
    / COUNT(DISTINCT m."molecule_id") AS percentage
FROM "molecule" m
JOIN "atom" a ON a."molecule_id" = m."molecule_id"
WHERE m."label" = '+';
```

```sql
/* Вычисляем процент карциногенных молекул среди связей типа '#' (тройные связи) */
SELECT
    /* Процент = (число тройных связей у карциногенных молекул * 100) / общее число связей у карциногенных молекул */
    (SUM(CASE WHEN b."bond_type" = '#' THEN 1 ELSE 0 END) * 100.0) / COUNT(b."bond_id") AS percent
FROM "molecule" m
JOIN "bond" b ON b."molecule_id" = m."molecule_id"
WHERE m."label" = '+';
```

```sql
/* Процент японских переводов среди наборов типа expansion */
SELECT
    /* Доля наборов типа expansion среди японских переводов, в процентах */
    (COUNT(*) FILTER (WHERE s."type" = 'expansion')::numeric
     / NULLIF(COUNT(*), 0)) * 100 AS percentage
FROM set_translations st
JOIN sets s ON s."code" = st."setcode"
WHERE st."language" = 'Japanese';
```

```sql
/* Доля карт Story Spotlight без текстового блока (istextless = 0) от общего числа карт */
SELECT
    /* Процент: карты Story Spotlight с текстовым блоком / все карты * 100 */
    (COUNT(*) FILTER (WHERE "isstoryspotlight" = 1 AND "istextless" = 0)::numeric
     / NULLIF(COUNT(*), 0)) * 100 AS percentage,
    /* Список ID таких карт */
    ARRAY_AGG("id") FILTER (WHERE "isstoryspotlight" = 1 AND "istextless" = 0) AS story_spotlight_ids
FROM "cards";
```

```sql
/* Доля карт без силы (power IS NULL или '*'), у которых язык — французский */
SELECT
    /* Процент: французские карты без силы / все карты без силы * 100 */
    (COUNT(*) FILTER (
        WHERE (c."power" IS NULL OR c."power" = '*')
          AND fd."language" = 'French'
    )::numeric
    / NULLIF(COUNT(*) FILTER (
        WHERE c."power" IS NULL OR c."power" = '*'
    ), 0)) * 100 AS percentage
FROM cards c
LEFT JOIN foreign_data fd
    ON fd."uuid" = c."uuid";
```

```sql
/* Доля карт с французским языком среди карт Story Spotlight */
SELECT
    /* Процент: французские Story Spotlight / все Story Spotlight * 100 */
    (COUNT(DISTINCT CASE WHEN fd."language" = 'French' THEN c."id" END)::numeric
     / NULLIF(COUNT(DISTINCT c."id"), 0)) * 100 AS percentage
FROM "cards" c
