```sql
/* Вычисляем процент постов с тегом 'r' среди постов, опубликованных пользователем Community */
SELECT
    /* Числитель: количество постов с тегом 'r', опубликованных Community */
    COUNT(DISTINCT CASE WHEN p."tags" LIKE '%<r>%' THEN p."id" END) * 100.0
    /
    /* Знаменатель: общее количество постов, опубликованных Community */
    NULLIF(COUNT(DISTINCT p."id"), 0) AS percentage
FROM "posts" p
JOIN "users" u ON u."id" = p."owneruserid"
WHERE u."displayname" = 'Community';
```

