```sql
/* Доля героев Marvel Comics среди супергероев ростом 150-180 см */
SELECT
    /* Процент героев Marvel Comics */
    (SUM(CASE WHEN p."publisher_name" = 'Marvel Comics' THEN 1 ELSE 0 END)::numeric
     / COUNT(p."id")::numeric) * 100 AS marvel_percentage
FROM "superhero" s
JOIN "publisher" p ON s."publisher_id" = p."id"
WHERE s."height_cm" BETWEEN 150 AND 180;
