```sql
/* Процент синих супергероинь среди всех супергероинь */
SELECT
    /* Вычисляем процент: (кол-во синих женщин / общее кол-во женщин) * 100 */
    (COUNT(CASE WHEN c."colour" = 'Blue' THEN 1 END)::numeric
     / NULLIF(COUNT(g."gender"), 0)) * 100 AS percentage
FROM "superhero" AS s
/* Присоединяем таблицу пола */
JOIN "gender" AS g
    ON s."gender_id" = g."id"
/* Присоединяем таблицу цвета кожи */
JOIN "colour" AS c
    ON s."skin_colour_id" = c."id"
/* Фильтруем только женщин */
WHERE g."gender" = 'Female';
```

```sql
/* Процент супергероев с alignment = 'Bad' и количество таких героев, изданных Marvel Comics */
SELECT
    /* Процент супергероев с alignment = 'Bad' от общего числа */
    (SUM(CASE WHEN a."alignment" = 'Bad' THEN 1 ELSE 0 END)::numeric
     / COUNT(s."id")::numeric) * 100 AS bad_percentage,
    /* Количество супергероев с alignment = 'Bad', изданных Marvel Comics */
    SUM(CASE WHEN a."alignment" = 'Bad' AND p."publisher_name" = 'Marvel Comics' THEN 1 ELSE 0 END) AS bad_marvel_count
FROM "superhero" s
LEFT JOIN "alignment" a ON s."alignment_id" = a."id"
LEFT JOIN "publisher" p ON s."publisher_id" = p."id";
```

